  trigger.addEventListener("click", () => {
    const isExpanded = trigger.getAttribute("aria-expanded") === "true";
    trigger.setAttribute("aria-expanded", String(!isExpanded));
    details.hidden = isExpanded;
  });

  wrapper.appendChild(trigger);
  wrapper.appendChild(details);

  return wrapper;
}

/**
 * FAQSection — renders a list of FAQItems into a container element.
 */
function FAQSection({ items, container }) {
  items.forEach((item, index) => {
    container.appendChild(FAQItem({ id: index + 1, ...item }));
  });
}

/* ── Data ── */
const FAQ_ITEMS = [
  {
    question: "How often should I feed my cat?",
    answer:
      "Most adult cats do well with two meals a day — once in the morning and once in the evening. Kittens under six months typically need three to four smaller meals daily to support their rapid growth.\n\nAlways provide access to fresh water and follow the portion guidance on your chosen food, adjusting for your cat's weight and activity level.",
  },
  {
    question: "Why does my cat knead me with their paws?",
    answer:
      "Kneading is a comforting behaviour that begins in kittenhood. Kittens knead their mother's belly to stimulate milk flow, and the motion becomes associated with warmth and security.\n\nWhen adult cats knead you, it's a sign of contentment and affection — your cat essentially sees you as a safe, beloved presence.",
  },
  {
    question: "How much sleep do cats need?",
    answer:
      "Cats are champion sleepers, averaging 12 to 16 hours per day. Senior cats and kittens may sleep even more — sometimes up to 20 hours.\n\nThis isn't laziness; cats are crepuscular predators whose bodies are built for short bursts of high energy followed by long rest periods to conserve energy for hunting.",
  },
  {
    question: "Do cats really need regular vet check-ups?",
    answer:
      "Yes — even if your cat appears healthy, annual wellness exams are important. Cats are known for masking illness, and routine check-ups allow vets to catch problems like dental disease, obesity, or early kidney issues before they progress.\n\nKittens and senior cats (7+ years) often benefit from more frequent visits every six months.",
  },
  {
    question: "Why do cats bring home 'gifts' like mice or birds?",
    answer:
      "This behaviour is rooted in instinct. In the wild, mother cats bring prey back to teach their kittens to hunt. Your indoor cat may see you as part of their social group and present prey as a gift or even an attempt to teach you to fend for yourself.\n\nKeeping cats indoors or using a well-fitted collar with a bell can help protect local wildlife.",
  },
  {
    question: "Is it true that cats always land on their feet?",
    answer:
      "Cats have an extraordinary righting reflex — a flexible spine and inner-ear balance system that allows them to rotate mid-air and orient their feet downward during a fall.\n\nHowever, 'always' is an overstatement. Very short falls don't give cats enough time to right themselves, and very long falls can still result in injury. Falls should never be considered safe.",
  },
  {
    question: "How can I tell if my cat is stressed?",
    answer:
      "Common signs of feline stress include hiding, over-grooming or loss of coat condition, changes in appetite, increased vocalization, or avoiding the litter box.\n\nStressors can include new pets, moving home, loud noises, or changes in routine. Providing vertical space, consistent schedules, and enrichment activities can help ease anxiety.",
  },
];

/* ── Bootstrap ── */
document.addEventListener("DOMContentLoaded", () => {
  const container = document.getElementById("faq-list");
  if (container) {
    FAQSection({ items: FAQ_ITEMS, container });
  }
});
