+ */
+function FAQItem({ id, question, answer }) {
+  const wrapper = document.createElement("div");
+  wrapper.className = "example";
+
+  const triggerId = `faq-trigger-${id}`;
+  const panelId = `faq-panel-${id}`;
+
+  /* ── Trigger button ── */
+  const trigger = document.createElement("button");
+  trigger.type = "button";
+  trigger.id = triggerId;
+  trigger.className = "faq-trigger";
+  trigger.setAttribute("aria-expanded", "false");
+  trigger.setAttribute("aria-controls", panelId);
+
+  const questionText = document.createElement("span");
+  questionText.textContent = question;
+
+  const chevron = document.createElementNS("http://www.w3.org/2000/svg", "svg");
+  chevron.setAttribute("aria-hidden", "true");
+  chevron.setAttribute("focusable", "false");
+  chevron.setAttribute("viewBox", "0 0 24 24");
+  chevron.setAttribute("fill", "none");
+  chevron.setAttribute("stroke", "currentColor");
+  chevron.setAttribute("stroke-width", "2");
+  chevron.setAttribute("stroke-linecap", "round");
+  chevron.setAttribute("stroke-linejoin", "round");
+  chevron.classList.add("chevron");
+
+  const path = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
+  path.setAttribute("points", "6 9 12 15 18 9");
+  chevron.appendChild(path);
+
+  trigger.appendChild(questionText);
+  trigger.appendChild(chevron);
+
+  /* ── Details panel ── */
+  const details = document.createElement("div");
+  details.id = panelId;
+  details.className = "details";
+  details.setAttribute("role", "region");
+  details.setAttribute("aria-labelledby", triggerId);
+  details.hidden = true;
+
+  // Support multi-paragraph answers (split on \n\n)
+  answer.trim().split(/\n\n+/).forEach((para) => {
+    const p = document.createElement("p");
+    p.textContent = para.trim();
+    details.appendChild(p);
+  });
+
+  /* ── Toggle behaviour ── */
+  trigger.addEventListener("click", () => {
+    const isExpanded = trigger.getAttribute("aria-expanded") === "true";
+    trigger.setAttribute("aria-expanded", String(!isExpanded));
+    details.hidden = isExpanded;
+  });
+
+  wrapper.appendChild(trigger);
+  wrapper.appendChild(details);
+
+  return wrapper;
+}
+
+/**
